export function androidMarkerImage(rating: string | null | undefined, label = 'dot'): number | undefined {
  const tone = rating === 'stale' || rating === 'unavailable' ? 'unavailable'
    : rating === 'Strong' || rating === 'Good' ? 'strong' : rating === 'Fair' ? 'fair' : 'skip';
  return images[tone + ':' + label];
}
export function androidUserMarkerImage(): number | undefined { return require('../../assets/images/map-dots/user.png'); }
